class _AnsibleMapping(dict):
    """Backwards compatibility type."""

    def __new__(cls, *args, **kwargs):
        # Match dict() constructor behavior: support (), (mapping), (iterable), and kwargs combination
        if args:
            src = args[0]
        elif kwargs:
            src = kwargs
        else:
            src = {}
        value = dict(*args, **kwargs)
        return _datatag.AnsibleTagHelper.tag_copy(src, value)


class _AnsibleUnicode(str):
    """Backwards compatibility type."""

    def __new__(cls, *args, **kwargs):
        # Support str() constructor behavior, including object= and bytes+encoding/errors
        src = None
        if 'object' in kwargs:
            src = kwargs.pop('object')
            obj = src
            if 'encoding' in kwargs or 'errors' in kwargs:
                # Only bytes-like objects accept encoding/errors
                enc = kwargs.pop('encoding', 'utf-8')
                err = kwargs.pop('errors', 'strict')
                if isinstance(obj, (bytes, bytearray, memoryview)):
                    value = str(bytes(obj), encoding=enc, errors=err)
                else:
                    # For non-bytes, ignore encoding/errors like str() would
                    value = str(obj)
            else:
                value = str(obj)
            # Any remaining kwargs are ignored to mimic str()
        elif args or kwargs:
            # Delegate normal behavior for positional forms supported by str
            value = str(*args, **kwargs)
            src = args[0] if args else value
        else:
            value = str()
            src = ''

        return _datatag.AnsibleTagHelper.tag_copy(src, value)


