    """Backwards compatibility type."""

    def __new__(cls, *args, **kwargs):
        # Match list() constructor behavior
        if args:
            src = args[0]
        else:
            src = []
        value = list(*args, **kwargs)
        return _datatag.AnsibleTagHelper.tag_copy(src, value)

